<?php

declare(strict_types=1);

namespace Sentinel\Services;

use DateTimeImmutable;
use PDOException;
use Sentinel\Core\HttpException;

final class ShiftAssignmentManagementService
{
    private const STATUSES = ['PLANNED','ASSIGNED','CONFIRMED','IN_PROGRESS','COMPLETED','MISSED','CANCELLED'];
    private const FIELDS = ['employee_id','contract_id','site_id','post_id','assignment_date','shift_name','shift_start_at','shift_end_at','assignment_status','check_in_window_start','check_in_window_end'];
    public function __construct(private readonly \Sentinel\Repositories\ShiftAssignmentRepository $shifts) {}
    public function listShiftAssignments(): array { try { return $this->shifts->listForCompany(); } catch (PDOException $e) { throw new HttpException(503,'Shift service unavailable.','shift_service_unavailable',$e); } }
    public function getShiftAssignment(string $id): array { try { $row=$this->shifts->findByIdForCompany($id); } catch(PDOException $e){throw new HttpException(503,'Shift service unavailable.','shift_service_unavailable',$e);} if($row===null) throw HttpException::notFound('Shift assignment not found.','shift_assignment_not_found'); return $row; }
    public function createShiftAssignment(array $input): array { $data=$this->validate($input,false); $this->validateReferences($data); $this->validateTimes($data); $this->rejectOverlap($data); try{return $this->shifts->createForCompany($data);}catch(PDOException $e){throw HttpException::conflict('Shift assignment could not be created.','shift_assignment_conflict');} }
    public function updateShiftAssignment(string $id,array $input): array { $existing=$this->getShiftAssignment($id); $patch=$this->validate($input,true); $effective=array_merge($existing,$patch); $this->validateReferences($effective); $this->validateTimes($effective); $this->rejectOverlap($effective,$id); try{$row=$this->shifts->updateForCompany($id,$patch);}catch(PDOException $e){throw HttpException::conflict('Shift assignment could not be updated.','shift_assignment_conflict');} if($row===null) throw HttpException::notFound('Shift assignment not found.','shift_assignment_not_found'); return $row; }
    private function validate(array $input,bool $update): array { $fields=[]; foreach(self::FIELDS as $f){if(array_key_exists($f,$input))$fields[$f]=$input[$f];} foreach(['employee_id','contract_id','site_id','post_id'] as $f){if(array_key_exists($f,$fields)&&$fields[$f]!==null)$fields[$f]=$this->positive($fields[$f],$f);} foreach(['assignment_date'] as $f){if(array_key_exists($f,$fields))$fields[$f]=$this->date($fields[$f],$f);} foreach(['shift_start_at','shift_end_at','check_in_window_start','check_in_window_end'] as $f){if(array_key_exists($f,$fields)&&$fields[$f]!==null)$fields[$f]=$this->date($fields[$f],$f);} if(array_key_exists('assignment_status',$fields)&&(!is_string($fields['assignment_status'])||!in_array($fields['assignment_status'],self::STATUSES,true)))throw HttpException::unprocessable('Assignment status is invalid.','invalid_assignment_status'); if(array_key_exists('shift_name',$fields)&&(!is_string($fields['shift_name'])||trim((string)$fields['shift_name'])===''||strlen(trim((string)$fields['shift_name']))>120))throw HttpException::unprocessable('Shift name is invalid.','invalid_shift_name'); if(!$update){foreach(['employee_id','assignment_date','shift_name','shift_start_at','shift_end_at'] as $r)if(!array_key_exists($r,$fields))throw HttpException::unprocessable(ucfirst(str_replace('_',' ',$r)).' is required.','invalid_'.$r);$fields['assignment_status']??='PLANNED';} return $fields; }
    private function validateReferences(array $d): void { try {if(!$this->shifts->employeeIsGuard((string)$d['employee_id']))throw HttpException::notFound('Guard not found.','guard_not_found'); if(isset($d['site_id'])&&!$this->shifts->siteBelongsToCompany((string)$d['site_id']))throw HttpException::notFound('Site not found.','site_not_found'); if(isset($d['post_id'])&&(!isset($d['site_id'])||!$this->shifts->postBelongsToSite((string)$d['post_id'],(string)$d['site_id'])))throw HttpException::notFound('Post not found.','post_not_found'); if(isset($d['contract_id'])&&!$this->shifts->contractBelongsToCompany((string)$d['contract_id']))throw HttpException::notFound('Contract not found.','contract_not_found');}catch(PDOException $e){throw new HttpException(503,'Shift service unavailable.','shift_service_unavailable',$e);} }
    private function validateTimes(array $d): void { $start=$this->parse($d['shift_start_at']??null);$end=$this->parse($d['shift_end_at']??null);if($start===null||$end===null||$end<=$start)throw HttpException::unprocessable('Shift end must be after shift start.','invalid_shift_time');if(isset($d['check_in_window_start'],$d['check_in_window_end'])&&$this->parse($d['check_in_window_end'])<$this->parse($d['check_in_window_start']))throw HttpException::unprocessable('Check-in window is invalid.','invalid_check_in_window'); }
    private function rejectOverlap(array $d,?string $exclude=null): void {try{if($this->shifts->overlappingShiftExists((string)$d['employee_id'],(string)$d['shift_start_at'],(string)$d['shift_end_at'],$exclude))throw HttpException::conflict('Employee has an overlapping shift assignment.','shift_schedule_conflict');}catch(PDOException $e){throw new HttpException(503,'Shift service unavailable.','shift_service_unavailable',$e);} }
    private function positive(mixed $v,string $f): int {if((!is_int($v)&&!(is_string($v)&&ctype_digit($v)))||(int)$v<1)throw HttpException::unprocessable(ucfirst($f).' is invalid.','invalid_'.$f);return(int)$v;}
    private function date(mixed $v,string $f): string {if(!is_string($v)||$this->parse($v)===null)throw HttpException::unprocessable(ucfirst(str_replace('_',' ',$f)).' is invalid.','invalid_'.$f);return$v;}
    private function parse(mixed $v): ?DateTimeImmutable {if(!is_string($v)||$v==='')return null;try{return new DateTimeImmutable($v);}catch(\Throwable){return null;}}
}